def estimate(points, x):
    """Return the piecewise linear interpolation for a single query.

    * ``points`` must be a list of (x, y) tuples sorted by x.
    * Outside the support, clamp to the nearest endpoint y.
    """
    if x <= points[0][0]:
        return points[0][1]
    if x >= points[-1][0]:
        return points[-1][1]
    for i in range(1, len(points)):
        left, right = points[i - 1], points[i]
        if x <= right[0]:
            # Linear interpolation between left and right
            return left[1] + (right[1] - left[1]) * (x - left[0]) / (right[0] - left[0])
    # Should never reach here
    return points[-1][1]

