def prepare(points):
    """Prepare a list of (x, y) samples.

    * Reject duplicate x values.
    * Reject an empty list of points.
    * Return a list sorted by x.
    """
    seen = {}
    for x, y in points:
        if x in seen:
            raise ValueError("duplicate coordinate")
        seen[x] = y
    if not seen:
        raise ValueError("empty samples")
    # Return sorted list of tuples
    return sorted(seen.items(), key=lambda p: p[0])

